/**
 * Generate robots.txt, sitemap.xml, and llms.txt from config/sot.json → geo.
 * Usage: node scripts/build-geo-assets.js
 */
/* eslint-env node */
/* eslint-disable no-console */

const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const SOT_PATH = path.join(ROOT, 'config', 'sot.json');

function loadSot() {
  return JSON.parse(fs.readFileSync(SOT_PATH, 'utf8'));
}

function buildRobotsTxt(geo) {
  const siteUrl = geo.siteUrl.replace(/\/$/, '');
  const lines = [
    '# Generated by scripts/build-geo-assets.js — edit config/sot.json → geo',
    '# LLMs: /llms.txt',
    '',
    'User-agent: *',
    'Allow: /'
  ];
  (geo.crawlers.disallowPaths || []).forEach(function (p) {
    lines.push('Disallow: ' + p);
  });
  lines.push('');
  (geo.crawlers.explicitBots || []).forEach(function (bot) {
    lines.push('User-agent: ' + bot);
    lines.push('Allow: /');
    (geo.crawlers.disallowPaths || []).forEach(function (p) {
      lines.push('Disallow: ' + p);
    });
    lines.push('');
  });
  lines.push('Sitemap: ' + siteUrl + '/sitemap.xml');
  lines.push('');
  return lines.join('\n');
}

function buildSitemapXml(geo) {
  const siteUrl = geo.siteUrl.replace(/\/$/, '');
  const lastmod = new Date().toISOString().slice(0, 10);
  const urls = (geo.sitemap.include || []).map(function (p) {
    const loc = siteUrl + (p.startsWith('/') ? p : '/' + p);
    const priority = p === '/en/' || p === '/en' ? '1.0' : '0.4';
    const changefreq = priority === '1.0' ? 'weekly' : 'monthly';
    return (
      '  <url>\n' +
      '    <loc>' +
      loc +
      '</loc>\n' +
      '    <lastmod>' +
      lastmod +
      '</lastmod>\n' +
      '    <changefreq>' +
      changefreq +
      '</changefreq>\n' +
      '    <priority>' +
      priority +
      '</priority>\n' +
      '  </url>'
    );
  });
  return (
    '<?xml version="1.0" encoding="UTF-8"?>\n' +
    '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' +
    urls.join('\n') +
    '\n</urlset>\n'
  );
}

function buildLlmsTxt(geo, brand) {
  const siteUrl = geo.siteUrl.replace(/\/$/, '');
  const lines = [
    '# ' + geo.llms.title,
    '',
    '> ' + geo.llms.summary,
    '',
    '## Ecosystem',
    '- ' + (geo.llms.related[0] || 'https://www.promptanatomy.app/') + ' — Prompt Anatomy AI Operating System (hub)',
    ''
  ];
  if (geo.entity && geo.entity.founder) {
    lines.push('## Creator');
    lines.push('- ' + geo.entity.founder.name + ' — founder of Prompt Anatomy');
    (geo.entity.founder.sameAs || []).forEach(function (url) {
      lines.push('  - ' + url);
    });
    lines.push('');
  }
  lines.push('## Key pages');
  (geo.llms.keyPages || []).forEach(function (page) {
    lines.push('- ' + siteUrl + page.url + ' — ' + page.label);
  });
  lines.push('');
  if ((geo.llms.related || []).length) {
    lines.push('## Related');
    geo.llms.related.forEach(function (url) {
      lines.push('- ' + url);
    });
    lines.push('');
  }
  lines.push('## Do not crawl');
  (geo.llms.doNotCrawl || []).forEach(function (p) {
    lines.push('- ' + siteUrl + p);
  });
  lines.push('');
  return lines.join('\n');
}

function main() {
  const sot = loadSot();
  if (!sot.geo) {
    console.error('config/sot.json missing geo block');
    process.exit(1);
  }
  const geo = sot.geo;
  fs.writeFileSync(path.join(ROOT, 'robots.txt'), buildRobotsTxt(geo), 'utf8');
  console.log('Wrote robots.txt');
  fs.writeFileSync(path.join(ROOT, 'sitemap.xml'), buildSitemapXml(geo), 'utf8');
  console.log('Wrote sitemap.xml');
  fs.writeFileSync(path.join(ROOT, 'llms.txt'), buildLlmsTxt(geo, sot.brand), 'utf8');
  console.log('Wrote llms.txt');
}

main();
